    const a = Math.exp(-n / (sampleRate * 0.01));
    this.ms = a * this.ms + (1 - a) * pow;
    const lvl = 10 * Math.log10(this.ms + 1e-12);
    const target = Math.min(p.depth[0], Math.max(0, (lvl - p.threshold[0]) * p.slope[0]));
